insert into public.profile (full_name, professional_title, typed_roles, short_intro, bio, email, phone, location, profile_image_url, hero_image_url, resume_url, availability_status, social_links, skill_tools) values
  ('Adrian Vale', 'Creative Designer & Digital Maker', array['Designer.', 'Developer.', 'Creative Director.', 'Digital Maker.']::text[], 'I create visual identities, interfaces and digital experiences for ambitious brands and modern products. Motion is my third dimension — I use it to make every interaction feel clear and memorable.', 'I''m a London-based designer with 7+ years of experience helping start-ups and established brands shape how they look, feel and move online. I''m available for freelance work — connect with me via email or phone.', 'hello@adrianvale.demo', '+44 20 7946 0000', 'London / Worldwide', '/demo/portrait.svg', '/demo/portrait.svg', null, 'Available for selected projects', '[{"platform":"facebook","url":"https://facebook.com/"},{"platform":"instagram","url":"https://instagram.com/"},{"platform":"linkedin","url":"https://linkedin.com/"}]'::jsonb, '[{"name":"Figma","icon":"figma"},{"name":"React","icon":"react"},{"name":"Next.js","icon":"nextjs"}]'::jsonb);
insert into public.services (title, short_description, icon_key, active, sort_order) values
  ('Creative Direction', 'I lead the visual story from first idea to launch, keeping every touchpoint consistent and intentional.', 'compass', true, 1),
  ('Web Design', 'Fast, responsive websites with thoughtful layouts, clear hierarchy and motion that guides the eye.', 'monitor', true, 2),
  ('Brand Identity', 'Logos, type systems and colour palettes that give your brand a recognisable, confident voice.', 'pen', true, 3),
  ('Motion Design', 'Micro-interactions and animated storytelling that make products feel alive — never distracting.', 'sparkles', true, 4),
  ('App Development', 'Modern web apps built with React and Next.js, engineered for performance and easy ownership.', 'code', true, 5),
  ('AI Product Visuals', 'Art-directed AI imagery and product visuals, refined by hand to match your brand standards.', 'wand', true, 6);
insert into public.projects (title, slug, category, year, client, role, intro, challenge, solution, result, cover_image_url, gallery, live_url, likes, featured, status, sort_order) values
  ('Nova Labs — Brand Experience', 'nova-labs', 'Brand Experience', 2026, 'Nova Labs', 'Creative Direction, UI Design', 'A complete brand and product experience for a research lab building tools for the next generation of scientists.', 'The team needed a fresh visual language that could scale across product, marketing and social — without losing the personality that made early customers fall in love with the brand.', 'We ran a two-week discovery sprint, defined a flexible design system, and prototyped key flows with motion from day one so every stakeholder could feel the experience before a line of production code was written.', 'A cohesive identity and product experience that launched on time. Conversion on the new landing pages rose by 38% and the design system cut new-page production time in half.', '/demo/project-nova-labs.svg', '["/demo/project-nova-labs.svg","/demo/project-morrow-studio.svg"]'::jsonb, 'https://example.com', 600, true, 'published', 1),
  ('Aether Skin — E-commerce Art Direction', 'aether-skin', 'E-commerce', 2025, 'Aether Skin', 'Art Direction, Web Design', 'Art direction and a conversion-focused storefront for a clean-beauty skincare label.', 'The team needed a fresh visual language that could scale across product, marketing and social — without losing the personality that made early customers fall in love with the brand.', 'We ran a two-week discovery sprint, defined a flexible design system, and prototyped key flows with motion from day one so every stakeholder could feel the experience before a line of production code was written.', 'A cohesive identity and product experience that launched on time. Conversion on the new landing pages rose by 38% and the design system cut new-page production time in half.', '/demo/project-aether-skin.svg', '["/demo/project-aether-skin.svg","/demo/project-kinetic-house.svg"]'::jsonb, 'https://example.com', 750, true, 'published', 2),
  ('Kinetic House — Digital Product', 'kinetic-house', 'Application', 2025, 'Kinetic House', 'Product Design, Motion', 'A mobile-first booking product for a network of independent design studios.', 'The team needed a fresh visual language that could scale across product, marketing and social — without losing the personality that made early customers fall in love with the brand.', 'We ran a two-week discovery sprint, defined a flexible design system, and prototyped key flows with motion from day one so every stakeholder could feel the experience before a line of production code was written.', 'A cohesive identity and product experience that launched on time. Conversion on the new landing pages rose by 38% and the design system cut new-page production time in half.', '/demo/project-kinetic-house.svg', '["/demo/project-kinetic-house.svg","/demo/project-pulse-fitness.svg"]'::jsonb, null, 630, true, 'published', 3),
  ('Nord Form — Identity System', 'nord-form', 'Branding', 2024, 'Nord Form', 'Brand Identity', 'A modular identity system for a Scandinavian furniture studio.', 'The team needed a fresh visual language that could scale across product, marketing and social — without losing the personality that made early customers fall in love with the brand.', 'We ran a two-week discovery sprint, defined a flexible design system, and prototyped key flows with motion from day one so every stakeholder could feel the experience before a line of production code was written.', 'A cohesive identity and product experience that launched on time. Conversion on the new landing pages rose by 38% and the design system cut new-page production time in half.', '/demo/project-nord-form.svg', '["/demo/project-nord-form.svg","/demo/project-nova-labs.svg"]'::jsonb, null, 360, false, 'published', 4),
  ('Morrow Studio — Campaign Visuals', 'morrow-studio', 'Campaign', 2024, 'Morrow Studio', 'Creative Direction, AI Visuals', 'A launch campaign mixing art-directed AI imagery with bold editorial typography.', 'The team needed a fresh visual language that could scale across product, marketing and social — without losing the personality that made early customers fall in love with the brand.', 'We ran a two-week discovery sprint, defined a flexible design system, and prototyped key flows with motion from day one so every stakeholder could feel the experience before a line of production code was written.', 'A cohesive identity and product experience that launched on time. Conversion on the new landing pages rose by 38% and the design system cut new-page production time in half.', '/demo/project-morrow-studio.svg', '["/demo/project-morrow-studio.svg","/demo/project-aether-skin.svg"]'::jsonb, 'https://example.com', 280, false, 'published', 5),
  ('Pulse Fitness — Mobile App', 'pulse-fitness', 'Application', 2023, 'Pulse', 'UI/UX Design', 'A workout tracking app with playful motion and a focus on daily habits.', 'The team needed a fresh visual language that could scale across product, marketing and social — without losing the personality that made early customers fall in love with the brand.', 'We ran a two-week discovery sprint, defined a flexible design system, and prototyped key flows with motion from day one so every stakeholder could feel the experience before a line of production code was written.', 'A cohesive identity and product experience that launched on time. Conversion on the new landing pages rose by 38% and the design system cut new-page production time in half.', '/demo/project-pulse-fitness.svg', '["/demo/project-pulse-fitness.svg","/demo/project-kinetic-house.svg"]'::jsonb, null, 690, false, 'published', 6);
