insert into public.blog_posts (title, slug, excerpt, content, cover_image_url, category, read_time, published_at, status) values
  ('Motion principles that make interfaces feel premium', 'motion-principles-premium-interfaces', 'Animation should explain, not decorate. Here are the five motion rules I use on every product.', 'Good motion is invisible. It answers questions before the user asks them: where did that come from, where did it go, what can I do next?
